<script setup lang="ts">
import { reactive, ref, watch } from 'vue'
import PageHeading from '@/components/PageHeading.vue'
import DeleteAccount from '@/components/DeleteAccount.vue'
import DigestPreview from '@/components/DigestPreview.vue'
import { workspace, saveSettings, exportData } from '@/lib/workspace'
import { describeError } from '@/lib/domain'
import { account } from '@/lib/account'
const form=reactive({timezone:'UTC',time:'',enabled:false}),busy=ref(false),error=ref(''),preview=ref(false),deleting=ref(false)
const zones=[...new Set(['UTC',Intl.DateTimeFormat().resolvedOptions().timeZone,...Intl.supportedValuesOf('timeZone')])]
watch(()=>workspace.data?.settings,s=>{if(s){form.timezone=s.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone;form.time=s.digest_time?.slice(0,5)||'';form.enabled=s.email_enabled}},{immediate:true})
async function submit(){busy.value=true;error.value='';try{await saveSettings(form.timezone,form.time||null,form.enabled)}catch(e){error.value=describeError(e)}finally{busy.value=false}}
async function download(){busy.value=true;error.value='';try{const data=await exportData();const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=account.sample?'lancealot-sample.json':'lancealot-export.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value=describeError(e)}finally{busy.value=false}}
</script>
<template><PageHeading title="Settings" subtitle="Your reminders, your records, your workspace." /><div v-if="!workspace.data?.settings.timezone" class="notice">Confirm your timezone to make Today use your local calendar date. Email stays off until you choose a time and enable it.</div><p v-if="error" class="notice error" role="alert">{{ error }}</p><div class="settings-grid"><div><section class="panel"><h2>Daily reminders</h2><p>Choose when you’d like to hear from Lancealot. Your in-app attention list stays available with email off.</p><form @submit.prevent="submit"><label class="toggle"><input v-model="form.enabled" type="checkbox" />Email me a daily digest</label><div class="fields"><div class="field"><label for="timezone">Timezone</label><select id="timezone" v-model="form.timezone" required><option v-for="z in zones" :key="z" :value="z">{{ z }}</option></select></div><div class="field"><label for="send-time">Local send time</label><input id="send-time" v-model="form.time" type="time" :required="form.enabled" /></div></div><p v-if="!workspace.features.digest" class="notice">{{ account.sample ? "Sample preferences only. No email is sent." : "Email delivery is not connected yet. You can save your preferences and use Today in the meantime." }}</p><div class="savebar"><button class="primary" :disabled="busy" type="submit">{{ busy?'Saving…':workspace.data?.settings.timezone?'Save changes':'Confirm timezone' }}</button></div></form></section><section class="panel"><h2>Your data</h2><p>Download your clients, projects, tasks, invoices and settings as JSON. Invoice amounts keep their original currencies.</p><button :disabled="busy" @click="download">Export data</button></section><section class="panel danger-panel"><h2>Delete account</h2><p>Permanently remove your account and active records. Access and new reminders stop when deletion begins. Export your data first if you want a copy.</p><p v-if="!workspace.features.deletion" class="secondary">Account removal is awaiting service setup and verification.</p><button class="danger" :disabled="!workspace.features.deletion" @click="deleting=true">Delete account</button></section></div><aside><section class="panel"><h2>Send status</h2><p>{{ ({ready:"Waiting for the next attempt",claimed:"Preparing a digest",sending:"Send outcome pending",accepted:"Accepted by email provider",unknown:"Email acceptance unknown",failed:"Email request failed",skipped:"No email needed"} as Record<string,string>)[workspace.features.status?.state || ""] || "No email attempts yet" }}</p><p class="secondary">Provider acceptance does not confirm inbox receipt.</p></section><section class="panel"><h2>Daily digest</h2><p>Preview your current outstanding follow-ups, project deadlines and overdue invoices.</p><p class="secondary">The preview does not send email. Invoice amounts stay in the app.</p><button class="quiet" @click="preview=true">Preview digest</button></section><section class="panel"><h2>One private workspace</h2><p>Your records belong to you. No teams or client sign-ins.</p></section></aside></div><DeleteAccount v-if="deleting" @close="deleting=false" /><DigestPreview v-if="preview" @close="preview=false" /></template>
